      T3:    { dcv: "T3", set: ON },
      T4:    { dcv: "T4", set: ON },
      LED1:  { led: "LED1", set: ON },
      T3off: { dcv: "T3" },
      LED1off: { led: "LED1" },
      mA:    { amps: "DCA 20m", red: "H21", black: "T2", lift: ["link@H19"], set: ON },
