      r1open:   { T3: [4.85, 5.10], T4: [0, 0.05], LED1: "off", mA: [0, 0.00005] },
      swdead:   { T1: [4.90, 5.10], T3: [0, 0.05], T4: [0, 0.05], LED1: "off" },
